import { useState, useEffect, useRef, useCallback } from "react";

/**
 * Tajrid Reader — standalone preview of the Phase 5 build.
 *
 * The real deliverable is a multi-file Vite + React + TypeScript project that
 * loads 2,550 records from a sharded static payload. This file is a faithful
 * single-file reduction of it so the interaction can be tried directly:
 * routing is internal state instead of react-router, and a 20-hadith excerpt
 * of the real generated payload is inlined instead of being fetched.
 *
 * Everything else is the same: the direction logic, the keyboard map, the
 * validation behaviour, and the text itself, which is the pipeline's own
 * output down to each vowel mark.
 */

const DATA = __DATA__;

// The join key, mirroring pipeline/normalise.py. Note the hamza rule is NOT
// uniform: alef-seated hamza folds to bare ALEF, waw- and yeh-seated hamza to
// bare HAMZA. In the real build this file is GENERATED from the Python so the
// two cannot drift.
const DIACRITICS = /[\u0640\u064B-\u0655\u0670]/g;
const LETTERS = {
  "\u0623": "\u0627", "\u0625": "\u0627", "\u0622": "\u0627",
  "\u0649": "\u064A", "\u0629": "\u0647",
  "\u0626": "\u0621", "\u0624": "\u0621",
};
function normalise(form) {
  let out = "";
  for (const ch of form.replace(DIACRITICS, "")) out += LETTERS[ch] ?? ch;
  return out;
}

/**
 * Search. Queries are normalised with the same function the lexicon joins on,
 * so typing `صلاه` finds `صَلَاةٍ` — a student looking a word up does not yet
 * know its vowelling, which is rather the point.
 *
 * Multiple terms are BEST-MATCH, not strict AND: the records matching the most
 * distinct terms win. Someone typing a half-remembered phrase should get the
 * closest hadith rather than nothing.
 */
function runSearch(query) {
  const terms = [...new Set(query.trim().split(/\s+/).map(normalise).filter(Boolean))];
  if (!terms.length) return { hits: [], terms };
  const scored = [];
  for (const n of NUMBERS) {
    const rec = DATA.records[String(n)].main;
    const keys = rec.t.map((t) => normalise(t[0]));
    const hit = new Set();
    keys.forEach((k) => { if (terms.includes(k)) hit.add(k); });
    if (!hit.size) continue;
    const first = keys.findIndex((k) => terms.includes(k));
    const lo = Math.max(0, first - 7), hi = Math.min(rec.t.length, first + 8);
    scored.push({
      n, matched: hit.size, kitab: rec.k ? rec.k.titleAr : null,
      lead: lo > 0, tail: hi < rec.t.length,
      parts: rec.t.slice(lo, hi).map((t, i) => ({
        text: t[0] + t[1], match: terms.includes(keys[lo + i]),
      })),
    });
  }
  const best = Math.max(...scored.map((s) => s.matched), 0);
  return { hits: scored.filter((s) => s.matched === best), terms };
}

const NUMBERS = Object.keys(DATA.records)
  .map(Number)
  .sort((a, b) => a - b);
const FIRST = NUMBERS[0];
const LAST = NUMBERS[NUMBERS.length - 1];

/* Fonts are subset to exactly the glyphs this excerpt uses and inlined, so the
   preview shows the real typographic decision rather than a system fallback.
   Amiri: a Bulaq-revival naskh, chosen on measurement — under a full harakat
   load it needs 1.90x its font size in vertical ink, more than Scheherazade New
   (1.80x) or Noto Naskh (1.40x), and here the marks ARE the content.
   Inter: forced by coverage. Transliteration needs ʿ (U+02BF) and ʾ (U+02BE);
   of five sans faces checked, only Inter has both. */
const FONT_CSS = `
@font-face{font-family:'AmiriSub';src:url(data:font/woff2;base64,) format('woff2');font-display:swap}
@font-face{font-family:'InterSub';src:url(data:font/woff2;base64,) format('woff2');font-display:swap}
.tj{
  --paper:#f5f7f9; --raised:#ffffff; --ink:#1b2227; --muted:#5c666f;
  --rule:#dde3e8; --accent:#1a5c6e; --accent-soft:#d8ecf1; --flag:#8c3a63;
  background:var(--paper); color:var(--ink);
  font-family:'InterSub', ui-sans-serif, system-ui, sans-serif;
}
@media (prefers-color-scheme: dark){
  .tj{ --paper:#141a1e; --raised:#1c2429; --ink:#e6ebee; --muted:#a7b2ba;
       --rule:#2f3940; --accent:#7cc7db; --accent-soft:#22343b; --flag:#dc9ec1; }
}
.tj-muted{color:var(--muted)}
.tj-rule{border-color:var(--rule)}
.tj-raised{background:var(--raised)}
.tj-fill{background:var(--rule)}
.tj-flag{color:var(--flag)}
.tj-hover:hover{background:var(--rule)}
.tj-arabic{font-family:'AmiriSub', serif}
/* Five size steps, and the LEADING FALLS AS THE SIZE RISES: the mark stack needs
   a fixed proportion of the em, so at 20px a line has ~2px of clearance and at
   40px ~7px. Small text needs proportionally more leading, not the same. */
.tj-body{font-family:'AmiriSub', serif}
.tj-s1{font-size:1.25rem;line-height:2.25}
.tj-s2{font-size:1.5rem;line-height:2.15}
.tj-s3{font-size:1.75rem;line-height:2.05}
.tj-s4{font-size:2.125rem;line-height:1.98}
.tj-s5{font-size:2.5rem;line-height:1.92}
.tj :focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:2px}
@media (prefers-reduced-motion: reduce){
  .tj *,.tj *::before,.tj *::after{transition-duration:.01ms !important;animation-duration:.01ms !important}
}
@media (max-width:1023px){
  .tj-sheet{position:fixed;left:0;right:0;bottom:0;z-index:40;max-height:68vh;overflow-y:auto;
            border-top:1px solid var(--rule);background:var(--raised);
            border-radius:14px 14px 0 0;box-shadow:0 -12px 40px rgba(0,0,0,.18);padding:20px}
  .tj-sheet-hidden{display:none}
}
`;

const ARABIC_STACK = "'AmiriSub', serif";

/**
 * DIRECTION — Arabic runs right to left, so moving FORWARD through the book
 * moves LEFT across the screen. Next sits on the left and answers to
 * ArrowLeft; previous sits on the right and answers to ArrowRight. Both are
 * labelled with words as well as arrows, because an arrow on its own is
 * ambiguous to a reader who carries both conventions.
 */
function neighbours(n) {
  const at = NUMBERS.indexOf(n);
  if (at === -1) return { prev: null, next: null };
  return {
    prev: at > 0 ? NUMBERS[at - 1] : null,
    next: at < NUMBERS.length - 1 ? NUMBERS[at + 1] : null,
  };
}

export default function TajridReader() {
  const [current, setCurrent] = useState(FIRST);
  const [selected, setSelected] = useState(null);
  // The real build persists these in localStorage; artifacts cannot use it, so
  // the preview keeps them in memory for the session.
  const [step, setStep] = useState(3);
  const [harakat, setHarakat] = useState(true);
  const [browserOpen, setBrowserOpen] = useState(false);
  const [view, setView] = useState("read");
  const [query, setQuery] = useState("");
  const [results, setResults] = useState(null);
  const [jump, setJump] = useState("");
  const [jumpError, setJumpError] = useState(null);
  const [history, setHistory] = useState([FIRST]);
  const jumpRef = useRef(null);

  const near = neighbours(current);

  const go = useCallback((n) => {
    setCurrent(n);
    setSelected(null);
    setView("read");
    setHistory((h) => [...h, n]);
    setBrowserOpen(false);
  }, []);

  const back = useCallback(() => {
    setHistory((h) => {
      if (h.length < 2) return h;
      const next = h.slice(0, -1);
      setCurrent(next[next.length - 1]);
      return next;
    });
  }, []);

  useEffect(() => {
    function onKey(e) {
      if (e.key === "Escape") {
        setBrowserOpen(false);
        return;
      }
      const el = e.target;
      const typing =
        el &&
        (el.tagName === "INPUT" ||
          el.tagName === "TEXTAREA" ||
          el.isContentEditable);
      if (typing || e.metaKey || e.ctrlKey || e.altKey) return;

      // While a word is focused the arrows belong to the reading pane, which
      // traverses word by word. Escape releases it and hands them back.
      const active = document.activeElement;
      if (active && active.dataset && active.dataset.token !== undefined) return;

      if (e.key === "ArrowLeft") {
        e.preventDefault();
        if (near.next) go(near.next);
      } else if (e.key === "ArrowRight") {
        e.preventDefault();
        if (near.prev) go(near.prev);
      } else if (e.key === "/") {
        e.preventDefault();
        jumpRef.current?.focus();
      }
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [near.next, near.prev, go]);

  function submitJump() {
    const t = jump.trim();
    if (!t) return;
    if (!/^\d+$/.test(t)) {
      setJumpError("أدخل رقمًا");
      return;
    }
    const n = Number(t);
    if (!DATA.records[String(n)]) {
      setJumpError(
        n >= 1 && n <= DATA.counts.hadith
          ? `الحديث ${n} خارج هذه المقتطفات (${FIRST}–${LAST})`
          : `النطاق ${FIRST} إلى ${LAST}`,
      );
      return;
    }
    setJumpError(null);
    setJump("");
    go(n);
  }

  const rec = DATA.records[String(current)];

  return (
    <div dir="rtl" lang="ar" className="tj min-h-screen">
      <style>{FONT_CSS}</style>
      <div className="mx-auto max-w-6xl px-5 py-7">
        <Banner />

        <header className="mb-7 flex flex-wrap items-start justify-between gap-4 border-b tj-rule pb-4">
          <div>
            <button
              type="button"
              onClick={() => go(FIRST)}
              className="block text-right text-lg leading-snug"
              style={{ fontFamily: ARABIC_STACK }}
            >
              {DATA.corpus.titleAr}
            </button>
            <p className="mt-1 text-xs tj-muted" dir="ltr" lang="en">
              {DATA.corpus.titleEn} · {DATA.corpus.author}
            </p>
          </div>

          <div className="flex flex-wrap items-start gap-3">
            <div
              role="radiogroup"
              aria-label="حجم الخط"
              className="flex items-end gap-0.5 rounded-md border tj-rule px-1.5 py-1"
            >
              {[1, 2, 3, 4, 5].map((v) => (
                <button
                  key={v}
                  type="button"
                  role="radio"
                  aria-checked={v === step}
                  aria-label={`حجم ${v} من 5`}
                  onClick={() => setStep(v)}
                  className="flex h-7 w-6 items-end justify-center"
                >
                  <span
                    aria-hidden="true"
                    className="w-2.5 rounded-t-sm"
                    style={{
                      height: `${4 + v * 3}px`,
                      background: v === step ? "var(--accent)" : "var(--rule)",
                    }}
                  />
                </button>
              ))}
            </div>
            <button
              type="button"
              onClick={() => setHarakat(!harakat)}
              aria-pressed={harakat}
              className="rounded-md border tj-rule px-2.5 py-1.5 text-sm transition-colors tj-hover"
            >
              <span className="tj-arabic text-base" aria-hidden="true">
                {harakat ? "بَ" : "ب"}
              </span>
              <span className="mr-2 text-xs tj-muted">
                {harakat ? "إخفاء الحركات" : "إظهار الحركات"}
              </span>
            </button>
            <button
              type="button"
              onClick={() => { setView(view === "search" ? "read" : "search"); }}
              aria-pressed={view === "search"}
              className="rounded-md border tj-rule px-3 py-1.5 text-sm transition-colors tj-hover"
            >
              بحث
            </button>
            <button
              type="button"
              onClick={() => setBrowserOpen(true)}
              className="rounded-md border tj-rule px-3 py-1.5 text-sm transition-colors tj-hover"
            >
              الكتب والأبواب
            </button>
            <div className="flex flex-col items-start gap-1">
              <div className="flex items-center gap-2">
                <label htmlFor="jump" className="text-sm tj-muted">
                  انتقل إلى
                </label>
                <input
                  id="jump"
                  ref={jumpRef}
                  type="text"
                  inputMode="numeric"
                  value={jump}
                  placeholder={`${FIRST}–${LAST}`}
                  onChange={(e) => {
                    setJump(e.target.value);
                    setJumpError(null);
                  }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") submitJump();
                    if (e.key === "Escape") e.target.blur();
                  }}
                  className="w-24 rounded-md border tj-rule tj-raised px-2 py-1 text-sm tabular-nums"
                />
                <button
                  type="button"
                  onClick={submitJump}
                  className="rounded-md border tj-rule px-2 py-1 text-sm transition-colors tj-hover"
                >
                  اذهب
                </button>
              </div>
              {/* Reserved height so an error cannot shift the header. */}
              <p className="text-xs text-rose-700" style={{ minHeight: "1rem" }}>
                {jumpError}
              </p>
            </div>
          </div>
        </header>

        <div style={{ minHeight: "24rem" }}>
          {view === "search" ? (
            <SearchView
              query={query}
              setQuery={setQuery}
              results={results}
              setResults={setResults}
              onGo={go}
            />
          ) : (
            <PageView rec={rec} selected={selected} onSelect={setSelected} step={step} harakat={harakat} />
          )}
        </div>

        <footer className="mt-10 border-t tj-rule pt-4">
          <nav className="flex items-center justify-between gap-4">
            <Step
              to={near.next}
              label="التالي"
              en="Next"
              arrow="←"
              side="next"
              onGo={go}
            />
            <div className="flex items-center gap-3">
              {history.length > 1 && (
                <button
                  type="button"
                  onClick={back}
                  className="rounded-md px-2 py-1 text-xs tj-muted transition-colors tj-hover"
                >
                  رجوع
                </button>
              )}
              <Step
                to={near.prev}
                label="السابق"
                en="Previous"
                arrow="→"
                side="prev"
                onGo={go}
              />
            </div>
          </nav>
          <p className="mt-3 text-center text-xs tj-muted" dir="ltr">
            ← next · → previous · / jump · Esc release · click a word
          </p>
        </footer>
      </div>

      {browserOpen && (
        <BookBrowser
          onClose={() => setBrowserOpen(false)}
          currentKitab={rec.main.k ? rec.main.k.index : null}
          onGo={go}
        />
      )}
    </div>
  );
}

function SearchView({ query, setQuery, results, setResults, onGo }) {
  return (
    <div className="mx-auto max-w-3xl">
      <div className="flex items-start gap-2">
        <input
          id="search-input"
          type="search"
          value={query}
          autoFocus
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") setResults(runSearch(query)); }}
          placeholder="اكتب كلمة أو أكثر — بالحركات أو بدونها"
          aria-label="ابحث في النص"
          dir="rtl"
          className="tj-arabic w-full rounded-md border tj-rule tj-raised px-3 py-2 text-xl"
        />
        <button
          type="button"
          onClick={() => setResults(runSearch(query))}
          className="shrink-0 rounded-md border tj-rule px-3 py-2.5 text-sm transition-colors tj-hover"
        >
          ابحث
        </button>
      </div>
      <p className="mt-2 text-xs tj-muted">
        الحركات غير مطلوبة؛ يُطابَق البحث على الصيغة المجرَّدة.
      </p>
      <div className="mt-6">
        {results === null ? null : results.hits.length === 0 ? (
          <div>
            <p>لا نتائج في هذه المقتطفات.</p>
            <p className="mt-2 text-sm leading-relaxed tj-muted">
              البحث يطابق الصيغة كما وردت، لا الجذر — فـ«كتب» لا تجد «مكتوب».
            </p>
          </div>
        ) : (
          <>
            <p className="mb-3 text-sm tj-muted">{results.hits.length} حديثًا</p>
            <ol className="space-y-1">
              {results.hits.map((h) => (
                <li key={h.n}>
                  <button
                    type="button"
                    onClick={() => onGo(h.n)}
                    className="block w-full rounded-md border border-transparent px-3 py-3 text-right transition-colors tj-hover"
                  >
                    <span className="mb-1 flex items-baseline gap-3 text-xs tj-muted">
                      <span className="tabular-nums text-base" style={{ color: "var(--ink)" }}>{h.n}</span>
                      {h.kitab && <span className="tj-arabic">{h.kitab}</span>}
                    </span>
                    <span className="tj-arabic block text-xl leading-loose" dir="rtl">
                      {h.lead ? "… " : ""}
                      {h.parts.map((pt, i) =>
                        pt.match ? (
                          <mark key={i} style={{ background: "var(--accent-soft)", color: "var(--ink)" }}>{pt.text}</mark>
                        ) : (
                          <span key={i}>{pt.text}</span>
                        ),
                      )}
                      {h.tail ? " …" : ""}
                    </span>
                  </button>
                </li>
              ))}
            </ol>
          </>
        )}
      </div>
    </div>
  );
}

function Banner() {
  return (
    <div className="mb-5 rounded-md border tj-rule px-4 py-2.5 text-xs leading-relaxed tj-muted">
      <span dir="ltr" lang="en" className="block">
        Standalone preview of the full build. New here: every word now shows{" "}
        <strong>its own entry from Lane's Lexicon</strong> — senses, labels and
        sources, unedited — in place of the single mechanically sampled line v1
        showed. Try{" "}
        <strong style={{ fontFamily: "'AmiriSub', serif" }}>صَلَاةٍ</strong> in
        hadith 38. The real build serves all{" "}
        {DATA.counts.hadith.toLocaleString()} hadith from a sharded payload; this
        file inlines {Object.keys(DATA.records).length} of them, with the longest
        Lane entries trimmed to keep it to one file.
      </span>
    </div>
  );
}

function Step({ to, label, en, arrow, side, onGo }) {
  const shared =
    "inline-flex items-center gap-2 rounded-md border px-3 py-2 text-sm";
  if (to === null) {
    return (
      <span
        aria-disabled="true"
        className={`${shared} cursor-default tj-rule tj-muted`}
      >
        {side === "next" && <span aria-hidden="true">{arrow}</span>}
        <span>{label}</span>
        {side === "prev" && <span aria-hidden="true">{arrow}</span>}
      </span>
    );
  }
  return (
    <button
      type="button"
      onClick={() => onGo(to)}
      aria-label={`${en} — ${label} (${to})`}
      className={`${shared} tj-rule transition-colors tj-hover`}
    >
      {side === "next" && <span aria-hidden="true">{arrow}</span>}
      <span>{label}</span>
      <span className="tabular-nums tj-muted">{to}</span>
      {side === "prev" && <span aria-hidden="true">{arrow}</span>}
    </button>
  );
}

/**
 * Requirement 3: the Arabic occupies the LEFT of the page and the right carries
 * the apparatus. Those are physical sides and the document is RTL, so in a
 * two-track grid the narrow track must be declared FIRST — track 1 is the
 * rightmost when the writing direction is right-to-left. Writing this the
 * other way round silently gives the margin the wide track.
 */
function PageView({ rec, selected, onSelect, step, harakat }) {
  const { main, add } = rec;
  return (
    <div className="grid gap-8 lg:grid-cols-4">
      <article className="lg:order-2 lg:col-span-3">
        <p className="mb-4 flex items-baseline gap-3 text-sm tj-muted">
          <span data-hadith-number className="text-3xl tabular-nums">{main.n}</span>
          {main.nc.length > 1 && <span>يشمل الحديثين {main.nc.join(" و")}</span>}
        </p>
        <ReadingPane
          rec={main}
          selected={selected}
          onSelect={onSelect}
          harakat={harakat}
          className={`tj-body tj-s${step}`}
        />

        {add.map((a) => (
          <section
            key={a.id}
            className="mt-8 border-t border-dashed tj-rule pt-5"
          >
            <p className="mb-3 text-xs tj-muted">
              زيادة الضياء الداغستاني — ليست من أصل الزبيدي
            </p>
            <ReadingPane
              rec={a}
              selected={null}
              onSelect={() => {}}
              harakat={harakat}
              className={`tj-body tj-s${Math.max(1, step - 1)} tj-muted`}
            />
          </section>
        ))}
      </article>

      <aside
        aria-label="تفاصيل الكلمة"
        className={
          "space-y-6 text-sm lg:order-1 lg:col-span-1 lg:rounded-lg lg:border lg:tj-rule lg:tj-raised lg:p-5 " +
          (selected === null ? "tj-sheet tj-sheet-hidden" : "tj-sheet")
        }
      >
        <WordPanel main={main} selected={selected} onSelect={onSelect} />
        <details className="border-t tj-rule pt-4">
          <summary className="cursor-pointer text-xs tj-muted">بيانات الحديث</summary>
          <div className="mt-3 space-y-4">
            {main.k && <Field label="الكتاب">{main.k.titleAr}</Field>}
            {main.b && <Field label="الباب">{main.b.titleAr}</Field>}
            {main.pg.length > 0 && (
              <Field label="الصفحة">
                <span className="tabular-nums">{main.pg.join("، ")}</span>
              </Field>
            )}
            {main.bk.length > 0 && (
              <Field label="صحيح البخاري">
                <span className="tabular-nums">{main.bk.join("، ")}</span>
              </Field>
            )}
          </div>
        </details>
      </aside>
    </div>
  );
}

const DIVERGENCE_COPY = {
  curated: {
    title: "Literal and technical senses differ",
    blurb:
      "The everyday sense of the root and the sense this word carries as a term of art are not the same.",
    tone: "strong",
  },
  divergent: {
    title: "Classical and modern senses diverge",
    blurb: "Reading this with its modern meaning will mislead you.",
    tone: "warn",
  },
  developed_sense: {
    title: "The modern sense grew out of the classical one",
    blurb: "Related, but the modern reading has travelled from where it started.",
    tone: "warn",
  },
  aligned: {
    title: "Classical and modern senses agree",
    blurb: "The modern meaning is safe here.",
    tone: "calm",
  },
};

const BINDING_COPY = {
  1: "Only one lexicon entry matches this spelling, so the reading is not in doubt.",
  2: "The vowelling was transferred from the matching word in a fully vocalised edition of Bukhārī.",
  3: "The vowelling was inferred from how the same collocation is read elsewhere.",
  4: "The vowelling is the most frequent reading of this spelling — a guess.",
  5: "No lexicon entry.",
};

/**
 * The word panel, ordered most-useful-first with provenance last.
 *
 * Two rules run through it. A section with nothing to say is not rendered —
 * no empty boxes, no lonely labels. And where an absence is MEANINGFUL, the
 * panel says why: a particle has no root by design, not by failure.
 *
 * Nothing is shown as more certain than it is. `ss` is one sampled definition
 * out of `lc`, and for salah that sample reads "the middle of the back of a
 * human being" — so it is labelled and sized as a sample, never as the meaning.
 */
function WordPanel({ main, selected, onSelect }) {
  const tok = selected === null ? null : main.t[selected];
  if (!tok) {
    const rarest = main.t
      .map((t, i) => [t, i])
      .filter(([t]) => t[2] && DATA.lex[t[2]])
      .sort((a, b) => DATA.lex[a[0][2]].fq - DATA.lex[b[0][2]].fq)[0];
    return (
      <div className="space-y-3">
        <p>Select any word to see how it works.</p>
        <p className="text-xs leading-relaxed tj-muted">
          You get its vowelling and transliteration, what it means in Modern
          Standard Arabic, its root and lemma, what the classical dictionaries
          say, and — where the two differ — the gap between them.
        </p>
        {rarest && (
          <button
            type="button"
            onClick={() => onSelect(rarest[1])}
            className="rounded-md border tj-rule px-3 py-1.5 transition-colors tj-hover"
          >
            <span style={{ fontFamily: ARABIC_STACK }}>{rarest[0][0]}</span>
            <span className="mr-2 text-xs tj-muted" dir="ltr">
              rarest word here — try it
            </span>
          </button>
        )}
      </div>
    );
  }

  const e = tok[2] ? DATA.lex[tok[2]] : null;
  if (!e) {
    return (
      <div>
        <p className="text-2xl" style={{ fontFamily: ARABIC_STACK }}>
          {tok[0]}
        </p>
        <p className="mt-2 text-xs tj-muted" dir="ltr">
          Not in the lexicon — 12 tokens in the whole corpus are not, all of them
          hamza spelling variants.
        </p>
      </div>
    );
  }
  const cl = e.lr ? DATA.cl[e.lr] : null;
  const div = DIVERGENCE_COPY[e.dv];
  const hasPair = Boolean(e.ls || e.ts);
  const distance = e.ov == null ? 0.5 : 1 - e.ov;
  const ruleWidth = Math.max(1, Math.round(distance * 6));

  return (
    <div className="space-y-6">
      <header>
        <p className="text-4xl leading-tight" dir="rtl" style={{ fontFamily: ARABIC_STACK }}>
          {e.v}
        </p>
        {e.dn && <p className="mt-1 text-sm italic tj-muted" dir="ltr">{e.dn}</p>}
        {e.p && (
          <span className="mt-2 inline-block rounded border tj-rule px-1.5 py-0.5 text-xs uppercase tracking-wide tj-muted">
            {e.p.replace(/_/g, " ")}
          </span>
        )}
      </header>

      {e.g && e.g.s.length > 0 && (
        <Sec title="المعنى" sub="Meaning">
          <p className="text-base" dir="ltr">{e.g.s.join(", ")}</p>
          {(e.g.c || e.g.f) && (
            <div className="mt-2 flex flex-wrap gap-1.5" dir="ltr">
              {(e.g.c || []).map((c, i) => (
                <span key={"c" + i} className="rounded tj-fill px-1.5 py-0.5 text-xs tj-muted" title="attached clitic">
                  {c.join(" / ")}
                </span>
              ))}
              {(e.g.f || []).map((f) => (
                <span key={f} className="rounded border tj-rule px-1.5 py-0.5 text-xs tj-muted" title="morphological feature">
                  {f}
                </span>
              ))}
            </div>
          )}
        </Sec>
      )}

      <Sec title="الجذر واللفظ" sub="Root and lemma">
        {e.rt ? (
          <div className="flex items-baseline gap-3">
            <span className="text-2xl" dir="rtl" style={{ fontFamily: ARABIC_STACK, letterSpacing: "0.35em" }}>
              {[...e.rt].join(" ")}
            </span>
            {cl && cl.nl != null && (
              <span className="text-xs tj-muted" dir="ltr">
                {cl.nl} lemma{cl.nl === 1 ? "" : "s"} in this corpus
              </span>
            )}
          </div>
        ) : (
          <p className="text-xs leading-relaxed tj-muted" dir="ltr">
            No root — particles, pronouns and proper nouns do not have one. About
            48% of tokens in this corpus are in that position by design.
          </p>
        )}
        {e.lm && (
          <p className="mt-3">
            <span className="text-xl" dir="rtl" style={{ fontFamily: ARABIC_STACK }}>{e.lm}</span>
            {e.ld && <span className="mr-2 text-sm italic tj-muted" dir="ltr">{e.ld}</span>}
          </p>
        )}
      </Sec>

      {(cl?.kw || DATA.le[e.ln]) && (
        <Sec title="المعنى الكلاسيكي" sub="Lane's Lexicon">
          {cl?.kw && (
            <ul className="mb-3 flex flex-wrap gap-1.5" dir="ltr">
              {cl.kw.map((k) => (
                <li key={k} className="rounded-full tj-fill px-2 py-0.5 text-xs">{k}</li>
              ))}
            </ul>
          )}
          <LaneEntry nodeid={e.ln} root={e.lr} />
        </Sec>
      )}

      {div && (
        hasPair ? (
          /* THE SIGNATURE. Facing columns divided by a gutter rule, the way a
             critical edition sets variant readings against each other — because
             that is what this is. The rule's WEIGHT carries overlap_score: a
             hairline means the senses nearly coincide, a heavy rule means they
             have pulled apart. The brief forbids printing the bare number, and
             rightly: 0.14 tells a student nothing, a thick rule tells them the
             gap is wide. No colour, no icon, no tinted box. */
          <section
            className="border-y tj-rule py-4"
            style={{ borderTopWidth: 1, borderBottomWidth: 1 }}
          >
            <h3 className="text-sm font-semibold" dir="ltr">{div.title}</h3>
            <p className="mt-0.5 text-xs leading-relaxed tj-muted" dir="ltr">{div.blurb}</p>
            <div className="mt-4 grid grid-cols-[1fr_auto_1fr] gap-x-4" dir="ltr">
              <div>
                <p className="text-xs uppercase tracking-widest tj-muted">Literal</p>
                <p className="mt-1 text-sm leading-snug">{e.ls || "—"}</p>
              </div>
              <div
                aria-hidden="true"
                className="justify-self-center"
                style={{ width: ruleWidth, background: "var(--ink)" }}
              />
              <div>
                <p className="text-xs uppercase tracking-widest tj-muted">
                  Technical{e.dm ? ` · ${e.dm}` : ""}
                </p>
                <p className="mt-1 text-sm leading-snug">{e.ts || "—"}</p>
              </div>
            </div>
            <p className="mt-3 text-xs leading-relaxed tj-muted" dir="ltr">
              {distance > 0.66
                ? "The rule between them is heavy: these senses have travelled a long way apart."
                : distance > 0.33
                  ? "The rule between them shows how far the two senses have separated."
                  : "A thin rule: the two senses still overlap closely."}
            </p>
          </section>
        ) : (
          <p className="text-xs leading-relaxed tj-muted" dir="ltr">
            <span className="font-medium" style={{ color: "var(--ink)" }}>{div.title}.</span>{" "}
            {div.blurb}
          </p>
        )
      )}

      <Sec title="في هذا الكتاب" sub="In this corpus">
        <p dir="ltr">
          <strong className="tabular-nums">{e.fq.toLocaleString()}</strong> occurrence
          {e.fq === 1 ? "" : "s"} across{" "}
          <strong className="tabular-nums">{e.df.toLocaleString()}</strong> of{" "}
          {DATA.counts.hadith.toLocaleString()} records · rank{" "}
          <span className="tabular-nums">{e.rk.toLocaleString()}</span>
        </p>
        {e.fq === 1 && (
          <p className="mt-1 text-xs tj-muted" dir="ltr">
            A hapax — it occurs exactly once in the whole book.
          </p>
        )}
        {e.ly && (
          <p className="mt-2 text-xs tj-muted" dir="ltr">
            {e.ly
              .split(",")
              .map((x) => x.split(":"))
              .filter((x) => x.length === 2)
              .map(([n, c]) => `${c} in ${n.replace("heading_", "")}`)
              .join(" · ")}
          </p>
        )}
      </Sec>

      {e.nm === 1 && (
        <section className="rounded-md border tj-rule p-3">
          <h3 className="text-sm font-semibold" dir="ltr">A person, not a word</h3>
          <p className="mt-0.5 text-xs tj-muted" dir="ltr">
            This form is in the gazetteer of names mined from the isnād attribution
            patterns. Where the lexical apparatus above is thin, that is why.
          </p>
        </section>
      )}

      <Provenance e={e} tier={tok[3]} />
    </div>
  );
}

const RUN = ["t", "ar", "i", "ref", "q", "trop"];
const SIGLA_NOTE =
  "Letters in brackets are Lane's sources — K = al-Qāmūs al-Muḥīṭ, S = al-Ṣiḥāḥ, M = al-Muḥkam, TA = Tāj al-ʿArūs.";

/**
 * Lane's entry for THIS word.
 *
 * v1 showed one sense per root, sampled mechanically. For صلو that sample read
 * "the middle of the back of a human being" — a real sense of the root, which
 * turns out to be sense A2 of this very entry, and a catastrophic thing to hand
 * a student as the meaning of salah.
 *
 * Nothing is selected on the reader's behalf: these are Lane's senses, in his
 * order, with his own labels (b2, A2) and his own sigla.
 */
function LaneEntry({ nodeid, root }) {
  const [expanded, setExpanded] = useState(false);
  const [showAll, setShowAll] = useState(false);
  const entry = nodeid ? DATA.le[nodeid] : null;
  const sib = root ? DATA.lr[root] : null;
  if (!entry) {
    return sib ? (
      <p className="text-xs tj-muted" dir="ltr">
        {sib.e.length} entries under this root; none matched this word's lemma.
      </p>
    ) : null;
  }
  const senses = entry.s;
  const visible = expanded ? senses : senses.slice(0, 2);
  const others = (sib?.e || []).filter((x) => x[0] !== nodeid);

  return (
    <>
      <p className="mb-2 flex items-baseline gap-2">
        <span className="tj-arabic text-xl" dir="rtl">{entry.h}</span>
        <span className="text-xs tj-muted" dir="ltr">
          this word&rsquo;s own entry{sib?.p ? ` · p. ${sib.p}` : ""}
        </span>
      </p>
      <ol className="space-y-2" dir="ltr">
        {visible.map((s, i) => (
          <li key={i} className="text-sm leading-relaxed">
            {s[0] && (
              <span className="ml-1.5 rounded tj-fill px-1 text-xs tj-muted">{s[0]}</span>
            )}
            {s[2].map((r, j) =>
              RUN[r[0]] === "ar" || RUN[r[0]] === "ref" ? (
                <span key={j} className="tj-arabic" dir="rtl">{r[1]}</span>
              ) : RUN[r[0]] === "i" || RUN[r[0]] === "trop" ? (
                <em key={j}>{r[1]}</em>
              ) : (
                <span key={j}>{r[1]}</span>
              ),
            )}
          </li>
        ))}
      </ol>
      {senses.length > 2 && (
        <button
          type="button"
          onClick={() => setExpanded(!expanded)}
          aria-expanded={expanded}
          className="mt-2 text-xs tj-muted underline underline-offset-2"
          dir="ltr"
        >
          {expanded ? "Show fewer senses" : `Show all ${entry.n} senses of this entry`}
        </button>
      )}
      {entry.tr && (
        <p className="mt-1 text-xs tj-muted" dir="ltr">
          Long entry, trimmed for this preview. The full build carries it whole.
        </p>
      )}
      {others.length > 0 && (
        <div className="mt-3 border-t tj-rule pt-2">
          <button
            type="button"
            onClick={() => setShowAll(!showAll)}
            aria-expanded={showAll}
            className="text-xs tj-muted underline underline-offset-2"
            dir="ltr"
          >
            {showAll ? "Hide" : `${others.length} other entries under this root`}
          </button>
          {showAll && (
            <ul className="mt-2 space-y-1.5">
              {others.map((o) => (
                <li key={o[0]} className="text-sm">
                  <span className="tj-arabic text-lg" dir="rtl">{o[1]}</span>
                  <span className="mr-2 text-xs tj-muted" dir="ltr">
                    {o[2]} sense{o[2] === 1 ? "" : "s"}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
      <p className="mt-3 text-xs leading-relaxed tj-muted" dir="ltr">{SIGLA_NOTE}</p>
    </>
  );
}

function Provenance({ e, tier }) {
  const [open, setOpen] = useState(false);
  const shaky = e.pa === "disagree" || tier === 4 || e.rv === 1;
  return (
    <section className="border-t tj-rule pt-3">
      {e.pa === "disagree" && (
        <p className="mb-2 text-xs tj-flag" dir="ltr">
          The root shown above may be wrong. This form is flagged where the two
          morphological analysers disagree, which happens on hollow and irregular
          verbs.
        </p>
      )}
      <button
        type="button"
        onClick={() => setOpen(!open)}
        aria-expanded={open}
        className="flex w-full items-center justify-between text-xs tj-muted"
        dir="ltr"
      >
        <span>How this reading was arrived at{shaky && !open ? " · worth checking" : ""}</span>
        <span aria-hidden="true">{open ? "▾" : "▸"}</span>
      </button>
      {open && (
        <div className="mt-2 space-y-1.5 text-xs" dir="ltr">
          <p className="tj-muted">{BINDING_COPY[tier]}</p>
          {e.vs && <Row label="Vowelling source">{e.vs}</Row>}
          {e.mc && <Row label="Morphology">{e.mc.replace(/_/g, " ")}</Row>}
          {e.pa && <Row label="Analyser agreement">{e.pa}</Row>}
          {e.rv === 1 && (
            <p className="tj-muted">
              The workbook could not settle this form's vowelling from context and
              fell back to its most frequent reading.
            </p>
          )}
        </div>
      )}
    </section>
  );
}

function Row({ label, children }) {
  return (
    <div className="flex gap-2">
      <span className="w-36 shrink-0 tj-muted">{label}</span>
      <span>{children}</span>
    </div>
  );
}

function Sec({ title, sub, children }) {
  return (
    <section>
      <h3 className="mb-1.5 flex items-baseline gap-2">
        <span className="text-xs tj-muted">{title}</span>
        <span className="text-xs uppercase tracking-wide tj-muted" dir="ltr">{sub}</span>
      </h3>
      {children}
    </section>
  );
}

/**
 * Each word is its own element, which is safe because Arabic shaping is
 * word-internal — letters join within a word and never across the space
 * between two. The separator is emitted as a bare text node BETWEEN the spans,
 * so the browser still sees an ordinary run of text.
 *
 * The selection halo is painted OUTSIDE the box with a spread box-shadow, so a
 * selected word occupies exactly the same geometry as an unselected one.
 */
const DIAC = /[\u064b-\u0655\u0670\u0640]/g;

function ReadingPane({ rec, selected, onSelect, className, harakat }) {
  const paneRef = useRef(null);
  const clickable = rec.t.map((t, i) => (t[2] ? i : -1)).filter((i) => i >= 0);

  useEffect(() => {
    if (selected === null) return;
    const el = paneRef.current?.querySelector(`[data-token="${selected}"]`);
    if (el && document.activeElement !== el) el.focus({ preventScroll: true });
  }, [selected, rec.id]);

  function step(delta) {
    if (!clickable.length) return;
    if (selected === null) {
      onSelect(delta === 1 ? clickable[0] : clickable[clickable.length - 1]);
      return;
    }
    const at = clickable.indexOf(selected);
    const target = clickable[at + delta];
    if (target !== undefined) onSelect(target);
  }

  // Arabic runs right to left, so the next word is to the LEFT.
  function onKeyDown(e) {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.key === "ArrowLeft") { e.preventDefault(); e.stopPropagation(); step(1); }
    else if (e.key === "ArrowRight") { e.preventDefault(); e.stopPropagation(); step(-1); }
    else if (e.key === "Home") { e.preventDefault(); e.stopPropagation(); onSelect(clickable[0]); }
    else if (e.key === "End") { e.preventDefault(); e.stopPropagation(); onSelect(clickable[clickable.length - 1]); }
    else if (e.key === "Escape") { e.stopPropagation(); onSelect(null); e.target.blur(); }
  }

  const firstClickable = clickable.length ? clickable[0] : null;

  return (
    <p
      ref={paneRef}
      dir="rtl"
      onKeyDown={onKeyDown}
      className={className}
    >
      {rec.ld}
      {rec.t.map((t, i) => {
        const [raw, punct, matchId, tier] = t;
        const surface = harakat ? raw : raw.replace(DIAC, "");
        if (!matchId) {
          return (
            <span key={i}>
              <span className="opacity-60" title="غير موجود في المعجم">{surface}</span>
              {punct}
            </span>
          );
        }
        const isSel = i === selected;
        return (
          <span key={i}>
            <span
              role="button"
              tabIndex={i === (selected ?? firstClickable) ? 0 : -1}
              data-token={i}
              data-confidence={tier}
              aria-pressed={isSel}
              onClick={() => onSelect(isSel ? null : i)}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  onSelect(isSel ? null : i);
                }
              }}
              className={
                "cursor-pointer rounded-sm outline-none transition-colors " +
                (isSel ? "" : "tj-hover")
              }
              style={{
                ...(isSel
                  ? { backgroundColor: "var(--accent-soft)", boxShadow: "0 0 0 0.16em var(--accent-soft)" }
                  : {}),
                ...(tier === 4
                  ? { textDecoration: "underline dotted", textUnderlineOffset: "0.3em" }
                  : {}),
              }}
            >
              {surface}
            </span>
            {punct}
          </span>
        );
      })}
    </p>
  );
}

function Field({ label, children }) {
  return (
    <div>
      <p className="text-xs tj-muted">{label}</p>
      <p className="mt-0.5 leading-relaxed">{children}</p>
    </div>
  );
}

function BookBrowser({ onClose, currentKitab, onGo }) {
  const [expanded, setExpanded] = useState(currentKitab);
  const firstOf = {};
  for (const n of NUMBERS) {
    const k = DATA.records[String(n)].main.k;
    if (k && firstOf[k.index] === undefined) firstOf[k.index] = n;
  }

  return (
    <div className="fixed inset-0 z-50">
      <button
        type="button"
        aria-label="إغلاق"
        onClick={onClose}
        style={{ backgroundColor: "rgba(0,0,0,0.35)" }}
        className="absolute inset-0 h-full w-full cursor-default"
      />
      <div
        role="dialog"
        aria-modal="true"
        aria-label="الكتب والأبواب"
        className="absolute inset-y-0 right-0 flex w-full max-w-md flex-col tj-raised shadow-2xl"
      >
        <header className="flex items-baseline justify-between border-b tj-rule px-5 py-4">
          <h2 className="text-lg">الكتب والأبواب</h2>
          <span className="text-xs tj-muted">
            {DATA.counts.kitab} كتابًا · {DATA.counts.bab} بابًا
          </span>
        </header>

        <div className="flex-1 overflow-y-auto px-2 py-2">
          <ul>
            {DATA.tree.map((k) => {
              const open = expanded === k.i;
              const target = firstOf[k.i];
              return (
                <li key={k.i}>
                  <div className="flex items-stretch gap-1">
                    <button
                      type="button"
                      onClick={() => setExpanded(open ? null : k.i)}
                      aria-expanded={open}
                      className="w-8 shrink-0 rounded-md text-xs tj-muted transition-colors tj-hover"
                    >
                      {k.b.length ? (open ? "▾" : "▸") : ""}
                    </button>
                    <button
                      type="button"
                      onClick={() => target && onGo(target)}
                      className={`flex-1 rounded-md px-2 py-2 text-right transition-colors tj-hover ${
                        currentKitab === k.i ? "font-semibold" : ""
                      }`}
                    >
                      <span className="ml-2 text-xs tabular-nums tj-muted">
                        {k.i}
                      </span>
                      {k.t}
                    </button>
                  </div>
                  {open && k.b.length > 0 && (
                    <ul className="mb-1 mr-8 border-r tj-rule pr-2">
                      {k.b.map((b) => (
                        <li key={b.i}>
                          <button
                            type="button"
                            onClick={() => target && onGo(target)}
                            className="w-full rounded-md px-2 py-1.5 text-right text-sm tj-muted transition-colors tj-hover"
                          >
                            {b.t}
                          </button>
                        </li>
                      ))}
                    </ul>
                  )}
                </li>
              );
            })}
          </ul>
          <p className="px-3 py-4 text-xs leading-relaxed tj-muted">
            هذه المقتطفات تعرض {DATA.tree.length} من {DATA.counts.kitab} كتابًا.
          </p>
        </div>

        <footer className="border-t tj-rule px-5 py-3">
          <button
            type="button"
            onClick={onClose}
            className="rounded-md border tj-rule px-3 py-1.5 text-sm transition-colors tj-hover"
          >
            إغلاق
            <span className="mr-2 text-xs tj-muted">Esc</span>
          </button>
        </footer>
      </div>
    </div>
  );
}
